WITH fixes(slug,position,expected,explanation) AS (VALUES
('contabilidade-balanco-patrimonial-estrutura',1,'A depreciação acumulada é classificada no passivo.','Errado. Depreciação acumulada é conta retificadora do ativo imobilizado, reduzindo seu valor contábil. Não é uma obrigação a pagar e, portanto, não integra o passivo.'),
('contabilidade-balanco-patrimonial-estrutura',3,'Ações em tesouraria são conta redutora do Patrimônio Líquido.','Correto. Ações que a companhia recomprou e mantém em tesouraria aparecem como dedução do patrimônio líquido; não são classificadas como investimento em si mesma no ativo.'),
('contabilidade-gabriel-rabelo-exemplos-cfc-2020-2',1,'Participação de 12% em dividendos totais de R$ 18.000 gera recebível de R$ 2.160.','Correto. Para calcular a parcela proporcional dos dividendos, multiplique R$ 18.000 por 0,12: R$ 2.160. O cálculo supõe que os 12% dão direito proporcional à distribuição informada.'),
('contabilidade-gabriel-rabelo-exemplos-cfc-2020-2',11,'O custo de matéria-prima consumida com EI 3 mil, compras 11 mil e EF 5 mil é de R$ 9 mil.','Correto. Consumo de matéria-prima = estoque inicial + compras − estoque final. Logo, 3.000 + 11.000 − 5.000 = R$ 9.000 consumidos no período.'),
('contabilidade-gabriel-rabelo-exemplos-cfc-2020-2',12,'Preço unitário R$ 600 e custo variável unitário R$ 200 geram margem de contribuição unitária R$ 400.','Correto. Margem de contribuição unitária = preço de venda unitário − custo variável unitário, considerando que não foram informadas outras despesas variáveis. Assim, 600 − 200 = R$ 400.'),
('contabilidade-impairment-cpc-01-baixa-ativos',1,'O valor recuperável é o menor entre o valor líquido de venda e o valor em uso.','Errado. O valor recuperável é o MAIOR entre o valor justo líquido de despesas de alienação e o valor em uso. Exemplo: se os valores forem R$ 80 mil e R$ 95 mil, o recuperável será R$ 95 mil.'),
('contabilidade-gabriel-rabelo-exemplos-cfc-2020-2',5,'A moeda funcional é a moeda do principal ambiente econômico da entidade.','Correto. A moeda funcional é aquela do ambiente econômico principal em que a entidade opera, conforme o CPC 02. Não é necessariamente a moeda em que as demonstrações são apresentadas.')
), matches AS (SELECT sm.id,f.position,f.explanation FROM study_materials sm JOIN fixes f ON f.slug=sm.slug WHERE sm.quiz->(f.position-1)->>'q'=f.expected)
UPDATE study_materials sm SET quiz=(SELECT jsonb_agg(CASE WHEN e.ordinality=m.position THEN jsonb_set(e.value,'{why}',to_jsonb(m.explanation)) ELSE e.value END ORDER BY e.ordinality) FROM jsonb_array_elements(sm.quiz) WITH ORDINALITY e(value,ordinality)),updated_at=now()
FROM matches m WHERE sm.id=m.id;